def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_my, last_opp = history[-1]

    streak_d = 0
    idx = n - 1
    while idx >= 0:
        if history[idx][1] == 'D':
            streak_d += 1
            idx -= 1
        else:
            break

    prev_c_run = 0
    while idx >= 0:
        if history[idx][1] == 'C':
            prev_c_run += 1
            idx -= 1
        else:
            break

    recent10_start = n - 10
    if recent10_start < 0:
        recent10_start = 0
    recent5_start = n - 5
    if recent5_start < 0:
        recent5_start = 0

    opp_c = 0
    opp_c10 = 0
    opp_c5 = 0
    my_c = 0
    mimic_num = 0
    mimic_den = 0
    uncond_num = 0
    uncond_den = 0

    for i in range(n):
        m, o = history[i]
        if m == 'C':
            my_c += 1
        if o == 'C':
            opp_c += 1
            if i >= recent10_start:
                opp_c10 += 1
            if i >= recent5_start:
                opp_c5 += 1

        if i > 0:
            pm = history[i - 1][0]
            if o == pm:
                mimic_num += 1
            mimic_den += 1
            if pm == 'D':
                uncond_den += 1
                if o == 'C':
                    uncond_num += 1

    overall_coop = opp_c / float(n)
    recent10 = opp_c10 / float(max(1, min(10, n)))
    recent5 = opp_c5 / float(max(1, min(5, n)))
    mimic = mimic_num / float(mimic_den) if mimic_den > 0 else 0.0
    uncond_rate = uncond_num / float(uncond_den) if uncond_den > 0 else 0.0
    my_rate = my_c / float(n)
    remaining = 100 - n

    if last_opp == 'D' and streak_d == 1 and last_my == 'C' and n <= 4 and rng.random() < 0.18:
        return 'C'

    if opp_c == 0 and n >= 5:
        return 'D'

    if overall_coop < 0.20 and recent10 < 0.30:
        return 'D'

    if last_opp == 'C':
        if uncond_num > 0 and uncond_rate >= 0.65 and overall_coop > 0.55 and recent10 > 0.40:
            if uncond_rate >= 0.85 and uncond_num >= 2 and overall_coop > 0.70 and recent10 > 0.55 and remaining <= 40:
                return 'D'
            if remaining <= 12:
                return 'D'
            if uncond_num >= 1 and uncond_rate >= 0.80 and overall_coop > 0.85 and recent10 > 0.80:
                if rng.random() < 0.22:
                    return 'D'
            if uncond_num >= 2 and rng.random() < 0.45:
                return 'D'
            if uncond_num >= 4 and rng.random() < 0.35:
                return 'D'

        if last_my == 'C' and uncond_num == 0 and my_rate > 0.50 and recent10 > 0.88 and n > 45 and remaining >= 8:
            if rng.random() < 0.035:
                return 'D'

        return 'C'

    high_trust4 = (prev_c_run >= 8 and overall_coop >= 0.62 and recent10 >= 0.52 and
                   mimic >= 0.60 and remaining >= 15)
    high_trust2 = (prev_c_run >= 5 and overall_coop >= 0.68 and recent10 >= 0.62 and
                   mimic >= 0.55 and remaining >= 8)
    single_trust = (prev_c_run >= 3 and overall_coop >= 0.72 and recent10 >= 0.72)

    if high_trust4 and streak_d <= 4:
        return 'C'
    if high_trust2 and streak_d <= 2:
        return 'C'
    if single_trust and streak_d == 1:
        return 'C'

    if (last_my == 'D' and prev_c_run >= 8 and overall_coop >= 0.50 and recent10 >= 0.30 and
            streak_d <= 6 and remaining >= 12):
        if rng.random() < 0.35:
            return 'C'

    if (last_my == 'D' and prev_c_run >= 3 and overall_coop >= 0.22 and recent10 >= 0.15 and
            streak_d <= 12 and remaining >= 6):
        if rng.random() < 0.08:
            return 'C'

    return 'D'
